{"code": "# Extract all lines that contain user information
import re

# Find all lines with "User:"
lines_with_user = []
for line in lines:
    if 'User:' in line:
        lines_with_user.append(line)

print(f"Found {len(lines_with_user)} lines with User")

# Let's extract user IDs and questions
users = {}
for line in lines_with_user:
    # Extract user ID
    user_match = re.search(r'User:\s*(\d+)', line)
    if user_match:
        user_id = user_match.group(1)
        # Extract the question (after "Instance:")
        question_match = re.search(r'Instance:\s*(.*?)(?:\n|$)', line)
        if question_match:
            question = question_match.group(1).strip()
            if user_id not in users:
                users[user_id] = []
            users[user_id].append(question)

print(f"Unique users: {len(users)}")
print("Sample users:", list(users.keys())[:10])"}

